        margin-top: 0.9rem;
        color: var(--color-link);
        font-weight: 700;
      }

      .editorial-card {
        display: grid;
        grid-template-rows: 11rem auto;
      }

      .editorial-card .visual::after {
        inset: 1rem auto auto 1rem;
        width: 3.8rem;
        height: 3.8rem;
      }

      .banner-card {
        background:
          linear-gradient(135deg, rgba(215, 180, 106, 0.16), rgba(158, 197, 255, 0.08)),
          var(--color-surface);
      }

      .banner-body {
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 1rem;
        align-items: center;
      }

      .status-region {
        min-height: 1.5rem;
        padding-top: 0.6rem;
      }

      .site-footer {
        margin-top: 3rem;
        padding: 2rem 0 3rem;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
      }

      .footer-grid {
        display: grid;
        gap: 1.5rem;
        grid-template-columns: 1.2fr 1fr;
      }

      .footer-nav {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
      }

      .footer-nav h2 {
        margin-bottom: 0.75rem;
        font-size: 1rem;
      }

      .footer-nav ul {
        list-style: none;
        padding: 0;
        margin: 0;
        display: grid;
        gap: 0.55rem;
      }

      .footer-nav a {
        color: var(--color-muted-text);
        text-decoration: none;
      }

      .footer-nav a:hover {
        color: var(--color-text);
      }

      @media (max-width: 960px) {
        .hero-panel,
        .footer-grid {
          grid-template-columns: 1fr;
        }

        .featured-item,
        .deal-item,
        .editorial-item,
        .editorial-item.editorial-wide {
          grid-column: span 6;
        }
      }

      @media (max-width: 700px) {
        .site-header {
          position: static;
        }

        .header-inner,
        .search-row,
        .banner-body,
        .footer-nav {
          grid-template-columns: 1fr;
        }

        .header-inner,
        .banner-body {
          display: grid;
        }

        .search-row {
          display: grid;
        }

        .featured-item,
        .deal-item,
        .editorial-item,
        .editorial-item.editorial-wide {
          grid-column: span 12;
        }

        .footer-nav {
          display: grid;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --color-bg: Canvas;
          --color-surface: Canvas;
          --color-surface-strong: Canvas;
          --color-surface-soft: Canvas;
          --color-text: CanvasText;
          --color-muted-text: CanvasText;
          --color-link: LinkText;
          --color-accent: ButtonFace;
          --color-border: ButtonBorder;
          --color-focus: Highlight;
          --color-success: Highlight;
          --shadow-elevated: none;
        }

        .button,
        .button-secondary,
        .product-button,
        .nav-list a,
        .utility-list a,
        .search-row input,
        .product-card,
        .editorial-card,
        .deal-card,
        .banner-card,
        .search-card,
        .spotlight-card,
        .stats-list li,
        .hero-panel {
          border: 1px solid ButtonBorder;
        }

        .button,
        .skip-link {
          color: ButtonText;
        }
      }
    </style>
  </head>
