+import { createRequire } from "node:module";
+import { pathToFileURL } from "node:url";
+import process from "node:process";
+import { chromium } from "playwright";
+
+const require = createRequire(import.meta.url);
+const pageUrl = pathToFileURL(new URL("./index.html", import.meta.url).pathname).href;
+const axePath = require.resolve("axe-core/axe.min.js");
+
+const browser = await chromium.launch({ headless: true });
+const page = await browser.newPage();
+
+await page.goto(pageUrl, { waitUntil: "load" });
+await page.addScriptTag({ path: axePath });
+
+const results = await page.evaluate(async () => window.axe.run());
+await browser.close();
+
+const wcag = results.violations.filter(
+  (violation) => !violation.tags.includes("best-practice")
+);
+const bestPractice = results.violations.filter((violation) =>
+  violation.tags.includes("best-practice")
+);
+
+const formatViolation = (violation) => ({
+  id: violation.id,
+  impact: violation.impact,
+  description: violation.description,
+  help: violation.help,
+  targets: violation.nodes.map((node) => node.target)
+});
