        --color-surface: #121722;
        --color-surface-strong: #181f2d;
        --color-surface-soft: #1d2636;
        --color-text: #f5f7fb;
        --color-muted-text: #b7c0d4;
        --color-link: #9ec5ff;
        --color-accent: #d7b46a;
        --color-border: #39465f;
        --color-focus: #ffd36b;
        --color-success: #7de2ae;
        --shadow-elevated: 0 24px 60px rgba(0, 0, 0, 0.35);
        --radius-lg: 28px;
        --radius-md: 18px;
        --radius-sm: 12px;
        --max-width: 1200px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #18233a 0, #0b0d12 45%),
          var(--color-bg);
        color: var(--color-text);
        line-height: 1.5;
      }

      a {
        color: var(--color-link);
      }

      a:hover {
        color: #c6dcff;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--color-focus);
        outline-offset: 3px;
      }

      img {
        max-width: 100%;
        display: block;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-220%);
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--color-focus);
        color: #111;
        font-weight: 700;
        text-decoration: none;
        z-index: 100;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
      }

      .site-shell {
        min-height: 100vh;
      }

      .container {
        width: min(var(--max-width), calc(100% - 2rem));
        margin: 0 auto;
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(18px);
        background: rgba(11, 13, 18, 0.85);
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      }

      .header-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1.5rem;
        padding: 1rem 0;
      }

      .brand {
        color: var(--color-text);
        text-decoration: none;
      }

      .brand-mark {
        display: inline-flex;
        align-items: center;
        gap: 0.8rem;
        font-weight: 800;
        letter-spacing: 0.04em;
        text-transform: uppercase;
      }

      .brand-orb {
        width: 2.25rem;
        height: 2.25rem;
        border-radius: 50%;
        background:
          radial-gradient(circle at 30% 30%, #ffe2a8 0, #d7b46a 35%, #664714 75%);
        box-shadow: 0 0 20px rgba(215, 180, 106, 0.35);
      }

      .nav-list,
      .utility-list,
      .stats-list,
      .grid-list {
        list-style: none;
        padding: 0;
        margin: 0;
      }

      .nav-list,
      .utility-list {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        gap: 0.75rem;
      }

      .nav-list a,
      .utility-list a {
        display: inline-flex;
        align-items: center;
        min-height: 2.75rem;
        padding: 0 0.95rem;
        border-radius: 999px;
        color: var(--color-text);
        text-decoration: none;
      }

      .nav-list a[aria-current="page"],
      .nav-list a:hover,
      .utility-list a:hover {
        background: rgba(255, 255, 255, 0.08);
      }

      .hero {
        padding: 3.5rem 0 2rem;
      }

      .hero-panel {
        display: grid;
        grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.95fr);
        gap: 1.5rem;
        padding: clamp(1.5rem, 4vw, 3rem);
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-lg);
        background:
          linear-gradient(135deg, rgba(215, 180, 106, 0.12), transparent 35%),
          linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01)),
          var(--color-surface);
        box-shadow: var(--shadow-elevated);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.55rem;
        margin-bottom: 1rem;
        padding: 0.4rem 0.8rem;
        border-radius: 999px;
        background: rgba(158, 197, 255, 0.12);
        color: #dbe8ff;
        font-size: 0.95rem;
        font-weight: 700;
      }

      h1,
      h2,
      h3 {
        margin-top: 0;
        line-height: 1.1;
      }

      h1 {
        max-width: 12ch;
        margin-bottom: 1rem;
        font-size: clamp(2.5rem, 5vw, 5rem);
      }

      .hero-copy p,
      .section-intro,
      .card-copy,
      .article-copy,
      .price-note,
      .search-label,
      .footer-copy,
      .status-text {
        color: var(--color-muted-text);
      }

      .hero-copy p {
        max-width: 56ch;
        margin-bottom: 1.5rem;
        font-size: 1.05rem;
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.9rem;
        margin-bottom: 1.75rem;
      }

      .button,
      .button-secondary,
      .product-button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 2.9rem;
        padding: 0.85rem 1.15rem;
        border: 1px solid transparent;
        border-radius: 999px;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        text-decoration: none;
      }

      .button {
        background: var(--color-accent);
        color: #1a1610;
      }

      .button:hover {
        background: #e4c584;
      }

      .button-secondary,
      .product-button {
        background: transparent;
        color: var(--color-text);
        border-color: var(--color-border);
      }

      .button-secondary:hover,
      .product-button:hover {
        background: rgba(255, 255, 255, 0.05);
      }

      .stats-list {
        display: flex;
        flex-wrap: wrap;
        gap: 1rem;
      }

      .stats-list li {
        min-width: 8rem;
        padding: 1rem;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-md);
        background: rgba(255, 255, 255, 0.02);
      }

      .stat-value {
        display: block;
        margin-bottom: 0.15rem;
        color: var(--color-text);
        font-size: 1.45rem;
        font-weight: 800;
      }

      .hero-aside {
        display: grid;
        gap: 1rem;
      }

      .search-card,
      .spotlight-card {
        padding: 1.25rem;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-md);
        background: var(--color-surface-strong);
      }

      .search-card h2,
      .spotlight-card h2 {
        margin-bottom: 0.35rem;
        font-size: 1.2rem;
      }

      .search-form {
        display: grid;
        gap: 0.75rem;
      }

      .search-row {
        display: flex;
        gap: 0.75rem;
      }

      .search-row input {
        flex: 1 1 auto;
        min-width: 0;
        min-height: 2.9rem;
        padding: 0.85rem 1rem;
        border: 1px solid var(--color-border);
        border-radius: 999px;
        background: #0e1420;
        color: var(--color-text);
        font: inherit;
      }

      .spotlight-meta {
        display: grid;
        gap: 0.6rem;
        padding: 0;
        margin: 1rem 0 0;
        list-style: none;
      }

      .spotlight-meta li {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        padding-bottom: 0.6rem;
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
      }

      .section-block {
        padding: 1.25rem 0 0;
      }

      .section-header {
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        align-items: end;
        gap: 1rem;
        margin-bottom: 1.5rem;
      }

      .section-header h2 {
        margin-bottom: 0.4rem;
        font-size: clamp(1.7rem, 3vw, 2.3rem);
      }

      .section-link {
        font-weight: 700;
      }

      .grid-list {
        display: grid;
        gap: 1.15rem;
        grid-template-columns: repeat(12, minmax(0, 1fr));
      }

      .product-card,
      .editorial-card,
      .deal-card,
      .banner-card {
        overflow: hidden;
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: var(--radius-md);
        background: var(--color-surface);
      }

      .featured-item,
      .deal-item,
      .editorial-item {
        grid-column: span 4;
      }

      .editorial-item.editorial-wide {
        grid-column: span 6;
      }

      .banner-item {
        grid-column: span 12;
      }

      .visual {
        position: relative;
        min-height: 13rem;
        padding: 1rem;
        background:
          linear-gradient(180deg, rgba(255, 255, 255, 0.03), transparent),
          var(--visual-gradient, linear-gradient(135deg, #18233a, #0e1420));
      }

      .visual::after {
        content: "";
        position: absolute;
        inset: auto 1rem 1rem auto;
        width: 5rem;
        height: 5rem;
        border-radius: 50%;
        border: 1px solid rgba(255, 255, 255, 0.18);
      }

      .badge-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.5rem;
      }

      .badge,
      .deal-badge {
        display: inline-flex;
        align-items: center;
        min-height: 2rem;
        padding: 0.35rem 0.7rem;
        border-radius: 999px;
        font-size: 0.9rem;
        font-weight: 700;
      }

      .badge {
        background: rgba(255, 255, 255, 0.08);
      }

      .deal-badge {
        background: rgba(125, 226, 174, 0.16);
        color: #d8ffe8;
      }

      .card-body,
      .banner-body {
        padding: 1.15rem;
      }

      .product-title a,
      .editorial-title a,
      .banner-title a {
        color: var(--color-text);
        text-decoration: none;
      }

      .product-title a:hover,
      .editorial-title a:hover,
      .banner-title a:hover {
        text-decoration: underline;
        text-underline-offset: 0.16em;
      }

      .product-meta,
      .deal-meta {
        display: flex;
        flex-wrap: wrap;
        gap: 0.65rem 1rem;
        align-items: center;
        margin-bottom: 1rem;
      }

      .price {
        font-size: 1.15rem;
        font-weight: 800;
      }

      .card-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        align-items: center;
      }

      .deal-card {
        padding: 1.15rem;
      }

      .deal-card h3 {
        margin-bottom: 0.55rem;
      }

      .deal-terms {
        display: inline-flex;
        margin-top: 0.9rem;
        color: var(--color-link);
        font-weight: 700;
      }

      .editorial-card {
        display: grid;
        grid-template-rows: 11rem auto;
      }

      .editorial-card .visual::after {
        inset: 1rem auto auto 1rem;
        width: 3.8rem;
        height: 3.8rem;
      }

      .banner-card {
        background:
          linear-gradient(135deg, rgba(215, 180, 106, 0.16), rgba(158, 197, 255, 0.08)),
          var(--color-surface);
      }

      .banner-body {
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 1rem;
        align-items: center;
      }

      .status-region {
        min-height: 1.5rem;
        padding-top: 0.6rem;
      }

      .site-footer {
        margin-top: 3rem;
        padding: 2rem 0 3rem;
        border-top: 1px solid rgba(255, 255, 255, 0.08);
      }

      .footer-grid {
        display: grid;
        gap: 1.5rem;
        grid-template-columns: 1.2fr 1fr;
      }

      .footer-nav {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
      }

      .footer-nav h2 {
        margin-bottom: 0.75rem;
        font-size: 1rem;
      }

      .footer-nav ul {
        list-style: none;
        padding: 0;
        margin: 0;
        display: grid;
        gap: 0.55rem;
      }

      .footer-nav a {
        color: var(--color-muted-text);
        text-decoration: none;
      }

      .footer-nav a:hover {
        color: var(--color-text);
      }

      @media (max-width: 960px) {
        .hero-panel,
        .footer-grid {
          grid-template-columns: 1fr;
        }

        .featured-item,
        .deal-item,
        .editorial-item,
        .editorial-item.editorial-wide {
          grid-column: span 6;
        }
      }

      @media (max-width: 700px) {
        .site-header {
          position: static;
        }

        .header-inner,
        .search-row,
        .banner-body,
        .footer-nav {
          grid-template-columns: 1fr;
        }

        .header-inner,
        .banner-body {
          display: grid;
        }

        .search-row {
          display: grid;
        }

        .featured-item,
        .deal-item,
        .editorial-item,
        .editorial-item.editorial-wide {
          grid-column: span 12;
        }

        .footer-nav {
          display: grid;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        html {
          scroll-behavior: auto;
        }

        *,
        *::before,
        *::after {
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
          transition-duration: 0.01ms !important;
        }
      }

      @media (forced-colors: active) {
        :root {
          --color-bg: Canvas;
          --color-surface: Canvas;
          --color-surface-strong: Canvas;
          --color-surface-soft: Canvas;
          --color-text: CanvasText;
          --color-muted-text: CanvasText;
          --color-link: LinkText;
          --color-accent: ButtonFace;
          --color-border: ButtonBorder;
          --color-focus: Highlight;
          --color-success: Highlight;
          --shadow-elevated: none;
        }

        .button,
        .button-secondary,
        .product-button,
        .nav-list a,
        .utility-list a,
        .search-row input,
        .product-card,
        .editorial-card,
        .deal-card,
        .banner-card,
        .search-card,
        .spotlight-card,
        .stats-list li,
        .hero-panel {
          border: 1px solid ButtonBorder;
        }

        .button,
        .skip-link {
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="app"></div>
    <script>
      const featuredProducts = [
        {
          name: "Aurora Wool Coat",
