          ]
        }
      ];

      const escapeHtml = (value) =>
        String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");

      const Header = () => `
        <header class="site-header">
          <div class="container header-inner">
            <a class="brand" href="#top" aria-label="Night Market home">
              <span class="brand-mark">
